26	// pushBranchIfNeeded pushes a branch to the given target if it has unpushed changes.
27	// The target can be a remote name (e.g., "origin") or a URL for direct push.
28	// When pushing to a URL, the "has unpushed" optimization is skipped since there are
29	// no remote tracking refs — git itself handles the no-op case.
30	// Does not check any settings — callers are responsible for gating.
31	func pushBranchIfNeeded(ctx context.Context, target, branchName string) error {
32		repo, err := OpenRepository(ctx)
33		if err != nil {
34			return nil //nolint:nilerr // Hook must be silent on failure
35		}
36	
37		// Check if branch exists locally
38		branchRef := plumbing.NewBranchReferenceName(branchName)
39		localRef, err := repo.Reference(branchRef, true)
40		if err != nil {
41			// No branch, nothing to push
42			return nil //nolint:nilerr // Expected when no sessions exist yet
43		}
44	
45		// Only check remote tracking refs when target is a remote name (not a URL).
46		// URLs don't have tracking refs, so we always attempt the push and let git handle it.
47		if !remote.IsURL(target) && !hasUnpushedSessionsCommon(repo, target, localRef.Hash(), branchName) {
48			return nil
49		}
50	
51		return doPushBranch(ctx, target, branchName)
52	}
