77	// doPushBranch pushes the given branch to the target with fetch+merge recovery.
78	// The target can be a remote name or a URL.
79	func doPushBranch(ctx context.Context, target, branchName string) error {
80		displayTarget := displayPushTarget(target)
81	
82		fmt.Fprintf(os.Stderr, "[entire] Pushing %s to %s...", branchName, displayTarget)
83		stop := startProgressDots(os.Stderr)
84	
85		// Try pushing first
86		result, err := tryPushSessionsCommon(ctx, target, branchName)
87		if err == nil {
88			finishPush(ctx, stop, result, target)
89			return nil
90		}
91		stop("")
92	
93		// Protected refs cannot be fixed by syncing and retrying.
94		var protectedErr *protectedRefError
95		if errors.As(err, &protectedErr) {
96			printProtectedRefBlock(os.Stderr, branchName, target)
97			return nil
98		}
99	
100		// Push failed - likely non-fast-forward. Try to fetch and rebase.
101		fmt.Fprintf(os.Stderr, "[entire] Syncing %s with remote...", branchName)
102		stop = startProgressDots(os.Stderr)
103	
104		if err := fetchAndRebaseSessionsCommon(ctx, target, branchName); err != nil {
105			stop("")
106			fmt.Fprintf(os.Stderr, "[entire] Warning: couldn't sync %s: %v\n", branchName, err)
107			printCheckpointRemoteHint(target)
108			return nil // Don't fail the main push
109		}
110		stop(" done")
111	
112		// Try pushing again after rebase
113		fmt.Fprintf(os.Stderr, "[entire] Pushing %s to %s...", branchName, displayTarget)
114		stop = startProgressDots(os.Stderr)
115	
116		if result, err := tryPushSessionsCommon(ctx, target, branchName); err != nil {
117			stop("")
118			fmt.Fprintf(os.Stderr, "[entire] Warning: failed to push %s after sync: %v\n", branchName, err)
119			printCheckpointRemoteHint(target)
120		} else {
121			finishPush(ctx, stop, result, target)
122		}
123	
124		return nil
125	}
