127	// printCheckpointRemoteHint prints a hint when a push to a checkpoint URL fails.
128	// Only prints when the target is a URL (not the user's default remote).
129	func printCheckpointRemoteHint(target string) {
130		if !remote.IsURL(target) {
131			return
132		}
133		fmt.Fprintln(os.Stderr, "[entire] A checkpoint remote is configured in Entire settings (.entire/settings.json or .entire/settings.local.json) but could not be reached.")
134		fmt.Fprintln(os.Stderr, "[entire] Checkpoints are saved locally but not synced. Ensure you have access to the checkpoint remote.")
135	}
