137	// settingsHintOnce ensures the settings commit hint prints at most once per process.
138	var settingsHintOnce sync.Once
139	
140	// checkpointsV2MigrationHintOnce ensures the checkpoints v2 migration hint prints at most once per process.
141	var checkpointsV2MigrationHintOnce sync.Once
