186	// isCheckpointRemoteCommitted returns true if the committed .entire/settings.json
187	// at HEAD contains a valid checkpoint_remote configuration. This is the true
188	// discoverability check: entire.io reads from committed project settings, not from
189	// local overrides or uncommitted changes.
190	func isCheckpointRemoteCommitted(ctx context.Context) bool {
191		cmd := exec.CommandContext(ctx, "git", "show", "HEAD:.entire/settings.json")
192		output, err := cmd.Output()
193		if err != nil {
194			return false // file doesn't exist at HEAD
195		}
196		// Parse the committed content and check for checkpoint_remote
197		committed, err := settings.LoadFromBytes(output)
198		if err != nil {
199			return false
200		}
201		return committed.GetCheckpointRemote() != nil
202	}
