219	// pushResult describes what happened during a push attempt.
220	type pushResult struct {
221		// upToDate is true when the remote already had all commits (nothing transferred).
222		upToDate bool
223	}
224	
225	// parsePushResult checks git push --porcelain output for ref status flags.
226	// In porcelain mode, each ref gets a tab-delimited status line:
227	//
228	//	<flag>\t<from>:<to>\t<summary>
229	//
230	// where flag '=' means the ref was already up-to-date. This is locale-independent,
231	// unlike the human-readable "Everything up-to-date" message.
232	func parsePushResult(output string) pushResult {
233		for _, line := range strings.Split(output, "\n") {
234			if strings.HasPrefix(line, "=\t") {
235				return pushResult{upToDate: true}
236			}
237		}
238		return pushResult{upToDate: false}
239	}
