241	// finishPush stops the progress dots and prints "already up-to-date" or "done"
242	// depending on the push result. Only prints the settings commit hint when new
243	// content was actually pushed.
244	func finishPush(ctx context.Context, stop func(string), result pushResult, target string) {
245		if result.upToDate {
246			stop(" already up-to-date")
247		} else {
248			stop(" done")
249			printSettingsCommitHint(ctx, target)
250		}
251		printCheckpointsV2MigrationHint(ctx)
252	}
