254	// tryPushSessionsCommon attempts to push the sessions branch.
255	func tryPushSessionsCommon(ctx context.Context, remoteName, branchName string) (pushResult, error) {
256		ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
257		defer cancel()
258	
259		result, err := remote.Push(ctx, remoteName, branchName)
260		outputStr := result.Output
261		if err != nil {
262			return pushResult{}, classifyPushFailure(ctx, outputStr, err)
263		}
264	
265		return parsePushResult(outputStr), nil
266	}
