277	// isProtectedRefRejection detects GitHub ruleset and branch-protection failures.
278	func isProtectedRefRejection(output string) bool {
279		return strings.Contains(output, "GH013") ||
280			strings.Contains(output, "Cannot update this protected ref") ||
281			strings.Contains(output, "protected branch hook declined")
282	}
283	
284	var errNonFastForward = errors.New("non-fast-forward")
285	
286	func isNonFastForwardRejection(output string) bool {
287		if strings.Contains(output, "non-fast-forward") {
288			return true
289		}
290		for _, line := range strings.Split(output, "\n") {
291			if strings.Contains(line, "[rejected]") && strings.Contains(line, "(fetch first)") {
292				return true
293			}
294		}
295		return strings.Contains(output, "Updates were rejected because the tip of your current branch is behind") ||
296			strings.Contains(output, "Updates were rejected because the remote contains work that you do not have locally")
297	}
298	
299	// classifyPushOutput maps failing push stderr to a typed error.
300	func classifyPushOutput(output string) error {
301		if isProtectedRefRejection(output) {
302			return &protectedRefError{output: output}
303		}
304		if isNonFastForwardRejection(output) {
305			return errNonFastForward
306		}
307		if strings.TrimSpace(output) == "" {
308			return errors.New("push failed")
309		}
310		return fmt.Errorf("push failed: %s", output)
311	}
312	
313	func classifyPushFailure(ctx context.Context, output string, pushErr error) error {
314		if strings.TrimSpace(output) != "" {
315			if pushErr != nil {
316				logging.Debug(ctx, "git push failed",
317					slog.String("error", pushErr.Error()),
318					slog.String("output", output),
319				)
320			}
321			return classifyPushOutput(output)
322		}
323		if pushErr != nil {
324			logging.Debug(ctx, "git push failed without output",
325				slog.String("error", pushErr.Error()),
326			)
327			return fmt.Errorf("push failed: %w", pushErr)
328		}
329		return errors.New("push failed")
330	}
