332	// printProtectedRefBlock explains that checkpoint syncing was blocked remotely.
333	func printProtectedRefBlock(w io.Writer, ref, target string) {
334		const banner = "[entire] ============================================================"
335		displayTarget := displayPushTarget(target)
336		fmt.Fprintln(w, banner)
337		fmt.Fprintf(w, "[entire] BLOCKED: remote rejected push to %s\n", ref)
338		fmt.Fprintln(w, "[entire] Reason:  GitHub branch protection or repository ruleset (e.g. GH013)")
339		fmt.Fprintf(w, "[entire] Target:  %s\n", displayTarget)
340		fmt.Fprintln(w, "[entire] Impact:  checkpoints are saved locally but NOT synced to this remote.")
341		fmt.Fprintln(w, "[entire] Action:  allow pushes to `entire/*` in your ruleset, or set")
342		fmt.Fprintln(w, "[entire]          `checkpoint_remote` in .entire/settings.json to a separate repo.")
343		fmt.Fprintln(w, banner)
344	}
