346	// fetchAndRebaseSessionsCommon fetches remote sessions and rebases local commits
347	// on top of the remote tip. Since checkpoint shards use unique paths, rebases
348	// always apply cleanly.
349	// The target can be a remote name or a URL.
350	func fetchAndRebaseSessionsCommon(ctx context.Context, target, branchName string) error {
351		ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
352		defer cancel()
353	
354		fetchTarget, err := remote.ResolveFetchTarget(ctx, target)
355		if err != nil {
356			return fmt.Errorf("resolve fetch target: %w", err)
357		}
358	
359		// Determine fetch refspec. When the resolved fetch target is a URL, use a
360		// temp ref; when it's still a remote name, use the standard remote-tracking
361		// ref.
362		var fetchedRefName plumbing.ReferenceName
363		var refSpec string
364		usedTempRef := remote.IsURL(fetchTarget)
365		if usedTempRef {
366			tmpRef := "refs/entire-fetch-tmp/" + branchName
367			refSpec = fmt.Sprintf("+refs/heads/%s:%s", branchName, tmpRef)
368			fetchedRefName = plumbing.ReferenceName(tmpRef)
369		} else {
370			refSpec = fmt.Sprintf("+refs/heads/%s:refs/remotes/%s/%s", branchName, target, branchName)
371			fetchedRefName = plumbing.NewRemoteReferenceName(target, branchName)
372		}
373	
374		// Use git CLI for fetch (go-git's fetch can be tricky with auth).
375		// Use --filter=blob:none for a partial fetch that downloads only commits
376		// and trees, skipping blobs. The merge only needs the tree structure to
377		// combine entries; blobs are already local or fetched on demand.
378		if output, fetchErr := remote.Fetch(ctx, remote.FetchOptions{
379			Remote:   fetchTarget,
380			RefSpecs: []string{refSpec},
381			NoTags:   true,
382		}); fetchErr != nil {
383			return fmt.Errorf("fetch failed: %s", output)
384		}
385	
386		repo, err := OpenRepository(ctx)
387		if err != nil {
388			return fmt.Errorf("failed to open git repository: %w", err)
389		}
390	
391		// Reconcile disconnected metadata branches before rebasing.
392		// The fetch above updated the remote-tracking ref, so reconciliation
393		// can compare fresh local vs remote. If disconnected (empty-orphan bug),
394		// this cherry-picks local commits onto remote tip, updating the local ref.
395		// If reconciliation fails, abort — proceeding to rebase on disconnected
396		// branches would silently combine unrelated histories.
397		if reconcileErr := ReconcileDisconnectedMetadataBranch(ctx, repo, fetchedRefName, os.Stderr); reconcileErr != nil {
398			return fmt.Errorf("metadata reconciliation failed: %w", reconcileErr)
399		}
400	
401		// Get local branch (re-read after potential reconciliation update)
402		localRef, err := repo.Reference(plumbing.NewBranchReferenceName(branchName), true)
403		if err != nil {
404			return fmt.Errorf("failed to get local ref: %w", err)
405		}
406	
407		// Get fetched ref (remote-tracking or temp ref, updated by the fetch above)
408		remoteRef, err := repo.Reference(fetchedRefName, true)
409		if err != nil {
410			return fmt.Errorf("failed to get remote ref: %w", err)
411		}
412	
413		// If local is already at or behind remote, fast-forward
414		if localRef.Hash() == remoteRef.Hash() {
415			return nil
416		}
417	
418		// Find merge base
419		repoPath, err := getRepoPath(repo)
420		if err != nil {
421			return fmt.Errorf("failed to get repo path: %w", err)
422		}
423		mergeBase, err := getMergeBase(ctx, repoPath, localRef.Hash().String(), remoteRef.Hash().String())
424		if err != nil {
425			return fmt.Errorf("failed to find merge base: %w", err)
426		}
427	
428		// If local is ancestor of remote (merge base == local), fast-forward to remote
429		if mergeBase == localRef.Hash() {
430			ref := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), remoteRef.Hash())
431			if err := repo.Storer.SetReference(ref); err != nil {
432				return fmt.Errorf("failed to fast-forward branch ref: %w", err)
433			}
434			if usedTempRef {
435				_ = repo.Storer.RemoveReference(fetchedRefName) //nolint:errcheck // cleanup is best-effort
436			}
437			return nil
438		}
439	
440		// Collect commits reachable from local but not from remote and cherry-pick
441		// them onto the remote tip. This preserves local-only commits even when the
442		// local metadata branch already contains old merge commits, while avoiding
443		// replaying shared ancestors older than the true merge-base.
444		localCommits, err := collectCommitsSince(ctx, repo, repoPath, localRef.Hash(), remoteRef.Hash())
445		if err != nil {
446			return fmt.Errorf("failed to collect local commits: %w", err)
447		}
448	
449		if len(localCommits) == 0 {
450			// No local-only commits — just point to remote
451			ref := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), remoteRef.Hash())
452			if err := repo.Storer.SetReference(ref); err != nil {
453				return fmt.Errorf("failed to update branch ref: %w", err)
454			}
455			if usedTempRef {
456				_ = repo.Storer.RemoveReference(fetchedRefName) //nolint:errcheck // cleanup is best-effort
457			}
458			return nil
459		}
460	
461		newTip, err := cherryPickOnto(ctx, repo, remoteRef.Hash(), localCommits)
462		if err != nil {
463			return fmt.Errorf("failed to rebase local commits onto remote: %w", err)
464		}
465	
466		// Update branch ref
467		newRef := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), newTip)
468		if err := repo.Storer.SetReference(newRef); err != nil {
469			return fmt.Errorf("failed to update branch ref: %w", err)
470		}
471	
472		// Clean up temp ref if we used one (best-effort, not critical if it fails)
473		if usedTempRef {
474			_ = repo.Storer.RemoveReference(fetchedRefName) //nolint:errcheck // cleanup is best-effort
475		}
476	
477		return nil
478	}
