480	// getMergeBase returns the merge base hash of two commits, or an error if they
481	// have no common ancestor.
482	func getMergeBase(ctx context.Context, repoPath, hashA, hashB string) (plumbing.Hash, error) {
483		ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
484		defer cancel()
485	
486		cmd := exec.CommandContext(ctx, "git", "merge-base", hashA, hashB)
487		cmd.Dir = repoPath
488		output, err := cmd.Output()
489		if err != nil {
490			return plumbing.ZeroHash, fmt.Errorf("git merge-base failed: %w", err)
491		}
492	
493		return plumbing.NewHash(strings.TrimSpace(string(output))), nil
494	}
495	
496	// collectCommitsSince returns non-merge commits reachable from tip but not from
497	// exclude, ordered oldest-first in topological order.
498	func collectCommitsSince(ctx context.Context, repo *git.Repository, repoPath string, tip, exclude plumbing.Hash) ([]*object.Commit, error) {
499		ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
500		defer cancel()
501	
502		// cherryPickOnto computes each commit's delta against its first parent, so
503		// replaying merge commits would incorrectly re-apply changes that arrived via
504		// non-first-parent history. Limit the replay set to non-merge commits.
505		cmd := exec.CommandContext(ctx, "git", "rev-list", "--reverse", "--topo-order", "--no-merges", exclude.String()+".."+tip.String())
506		cmd.Dir = repoPath
507		output, err := cmd.Output()
508		if err != nil {
509			return nil, fmt.Errorf("git rev-list failed: %w", err)
510		}
511	
512		lines := strings.Fields(string(output))
513		if len(lines) > MaxCommitTraversalDepth {
514			return nil, fmt.Errorf("commit chain exceeded %d commits; aborting rebase", MaxCommitTraversalDepth)
515		}
516	
517		commits := make([]*object.Commit, 0, len(lines))
518		for _, line := range lines {
519			hash := plumbing.NewHash(line)
520			commit, commitErr := repo.CommitObject(hash)
521			if commitErr != nil {
522				return nil, fmt.Errorf("failed to get commit %s: %w", hash, commitErr)
523			}
524			if len(commit.ParentHashes) > 1 {
525				continue
526			}
527			commits = append(commits, commit)
528		}
529	
530		return commits, nil
531	}
