533	// startProgressDots prints dots to w every second until the returned stop function
534	// is called. The stop function prints the given suffix and a newline.
535	func startProgressDots(w io.Writer) func(suffix string) {
536		done := make(chan struct{})
537		stopped := make(chan struct{})
538		go func() {
539			defer close(stopped)
540			ticker := time.NewTicker(time.Second)
541			defer ticker.Stop()
542			for {
543				select {
544				case <-done:
545					return
546				case <-ticker.C:
547					fmt.Fprint(w, ".")
548				}
549			}
550		}()
551		return func(suffix string) {
552			close(done)
553			<-stopped // Wait for goroutine to finish before writing suffix
554			fmt.Fprintln(w, suffix)
555		}
556	}
