558	// createMergeCommitCommon creates a merge commit with multiple parents.
559	func createMergeCommitCommon(ctx context.Context, repo *git.Repository, treeHash plumbing.Hash, parents []plumbing.Hash, message string) (plumbing.Hash, error) {
560		authorName, authorEmail := GetGitAuthorFromRepo(repo)
561		now := time.Now()
562		sig := object.Signature{
563			Name:  authorName,
564			Email: authorEmail,
565			When:  now,
566		}
567	
568		commit := &object.Commit{
569			TreeHash:     treeHash,
570			ParentHashes: parents,
571			Author:       sig,
572			Committer:    sig,
573			Message:      message,
574		}
575	
576		checkpoint.SignCommitBestEffort(ctx, commit)
577	
578		obj := repo.Storer.NewEncodedObject()
579		if err := commit.Encode(obj); err != nil {
