70	func pushV2RefsWithRecovery(ctx context.Context, target string, refs []plumbing.ReferenceName) []v2RefPushResult {
71		resultsByRef := make(map[plumbing.ReferenceName]v2RefPushResult, len(refs))
72		var retryRefs []plumbing.ReferenceName
73	
74		for _, result := range tryPushV2Refs(ctx, target, refs) {
75			if result.err == nil {
76				resultsByRef[result.refName] = result
77				continue
78			}
79			if !errors.Is(result.err, errNonFastForward) {
80				resultsByRef[result.refName] = result
81				continue
82			}
83	
84			shortRef := shortRefName(result.refName)
85			if err := fetchAndMergeRef(ctx, target, result.refName); err != nil {
86				resultsByRef[result.refName] = v2RefPushResult{
87					refName: result.refName,
88					err:     fmt.Errorf("couldn't sync %s: %w", shortRef, err),
89				}
90				continue
91			}
92			retryRefs = append(retryRefs, result.refName)
93		}
94	
95		if len(retryRefs) > 0 {
96			for _, result := range tryPushV2Refs(ctx, target, retryRefs) {
97				if result.err != nil {
98					result.err = fmt.Errorf("failed to push %s after sync: %w", shortRefName(result.refName), result.err)
99				}
100				resultsByRef[result.refName] = result
101			}
102		}
103	
104		results := make([]v2RefPushResult, 0, len(refs))
105		for _, refName := range refs {
106			result, ok := resultsByRef[refName]
107			if !ok {
108				result = v2RefPushResult{
109					refName: refName,
110					err:     errors.New("push result missing"),
111				}
112			}
113			results = append(results, result)
114		}
115		return results
116	}
