// remains the source of truth and the next successful condensation
// re-derives the compact tree from scratch.
func writeCompactRef(ctx context.Context, repo *git.Repository, opts cpkg.WriteCommittedOptions) {
	v2URL, err := remote.FetchURL(ctx)
	if err != nil {
		logging.Debug(ctx, "manual-commit condensation: using origin for compact-ref fetch remote",
